async function main() {
  const conn = await mysql.createConnection({
    host:     process.env.DB_HOST     || 'localhost',
    port:     parseInt(process.env.DB_PORT || '3306'),
    user:     process.env.DB_USERNAME || 'root',
    password: process.env.DB_PASSWORD || '',
    database: process.env.DB_DATABASE,
  });

  const passwordHash = await bcrypt.hash(DEFAULT_PASSWORD, 10);
  console.log(`\n=== IMPORT 896 NHÂN VIÊN BỆNH VIỆN HỮU NGHỊ ===`);
  console.log(`Password mặc định: ${DEFAULT_PASSWORD}\n`);

  // Load departments
  const [deptRows] = await conn.execute('SELECT id, name FROM departments');
  const deptMap = new Map();
  for (const d of deptRows) deptMap.set(d.name, d.id);

  // Load existing emails + CCCDs
  const [existingUsers] = await conn.execute('SELECT email, cccd FROM users');
  const usedEmails = new Set(existingUsers.map(u => u.email));
  const usedCccds  = new Set(existingUsers.filter(u => u.cccd).map(u => u.cccd));

  let created = 0, skipped = 0, errors = 0;

  for (const [dept, name, dob, gender, position, trinhdo, cccd, role] of STAFF) {
    const deptId = deptMap.get(dept);
    if (!deptId) {
      console.log(`⚠️  Không tìm thấy khoa: "${dept}" — ${name}`);
      errors++;
      continue;
    }

    // Bỏ qua nếu CCCD đã tồn tại
    if (cccd && usedCccds.has(cccd)) {
      skipped++;
      continue;
    }

    // Tạo email unique
    let baseEmail = removeDiacritics(name) + '@bvhn.vn';
    let email = baseEmail;
    let suffix = 1;
    while (usedEmails.has(email)) {
      email = baseEmail.replace('@', `${suffix}@`);
      suffix++;
    }
    usedEmails.add(email);
    if (cccd) usedCccds.add(cccd);

    const dobFormatted = parseDate(dob);
    const genderVal    = gender === 'M' ? 'male' : gender === 'F' ? 'female' : null;

    try {
      const id = crypto.randomUUID();
      await conn.execute(
        `INSERT INTO users
          (id, full_name, email, password_hash, role, department_id, is_active, must_change_password,
           position, qualification, cccd, date_of_birth, gender)
         VALUES (?, ?, ?, ?, ?, ?, 1, 1, ?, ?, ?, ?, ?)`,
        [id, name, email, passwordHash, role, deptId,
         position || null, trinhdo || null, cccd || null, dobFormatted, genderVal]
      );
      created++;
      if (created % 50 === 0) console.log(`  ... đã tạo ${created} tài khoản`);
    } catch (err) {
      console.log(`❌ Lỗi: ${name} — ${err.message}`);
      errors++;
    }
  }

  await conn.end();
  console.log(`\n=== KẾT QUẢ ===`);
  console.log(`✅ Tạo mới: ${created}`);
  console.log(`⏭️  Bỏ qua (đã tồn tại): ${skipped}`);
  console.log(`❌ Lỗi: ${errors}`);
  console.log(`\nPassword mặc định: ${DEFAULT_PASSWORD}`);
  console.log('Tổng nhân viên trong danh sách:', STAFF.length);
}

main().catch(err => {
  console.error('❌ Lỗi nghiêm trọng:', err.message);
  process.exit(1);
});
